import type {
  CompetitionSummary,
  CreateLeagueRequest,
  LeagueDetail,
  LeagueSummary,
} from "@fantappero/contracts";
import { apiRequest } from "./client";

export function fetchCompetitions(accessToken: string): Promise<CompetitionSummary[]> {
  return apiRequest<CompetitionSummary[]>("/leagues/competitions", { accessToken });
}

export function fetchMyLeagues(accessToken: string): Promise<LeagueSummary[]> {
  return apiRequest<LeagueSummary[]>("/leagues/mine", { accessToken });
}

export function createLeague(
  accessToken: string,
  payload: CreateLeagueRequest,
): Promise<LeagueDetail> {
  return apiRequest<LeagueDetail>("/leagues", {
    method: "POST",
    accessToken,
    body: payload,
  });
}

import type {
  CompetitionSummary,
  CreateLeagueRequest,
  LeagueAdminPanel,
  LeagueDetail,
  LeagueRules,
  LeagueSummary,
  UpdateLeagueRulesRequest,
} from "@fantappero/contracts";
import { apiRequest } from "./client";

export function fetchCompetitions(accessToken: string): Promise<CompetitionSummary[]> {
  return apiRequest<CompetitionSummary[]>("/leagues/competitions", { accessToken });
}

export function fetchMyLeagues(accessToken: string): Promise<LeagueSummary[]> {
  return apiRequest<LeagueSummary[]>("/leagues/mine", { accessToken });
}

export function createLeague(
  accessToken: string,
  payload: CreateLeagueRequest,
): Promise<LeagueDetail> {
  return apiRequest<LeagueDetail>("/leagues", {
    method: "POST",
    accessToken,
    body: payload,
  });
}

export function fetchLeagueAdminPanel(
  accessToken: string,
  leagueId: string,
): Promise<LeagueAdminPanel> {
  return apiRequest<LeagueAdminPanel>(`/leagues/${leagueId}/amministrazione`, { accessToken });
}

export function updateLeagueRules(
  accessToken: string,
  leagueId: string,
  payload: UpdateLeagueRulesRequest,
): Promise<LeagueRules> {
  return apiRequest<LeagueRules>(`/leagues/${leagueId}/amministrazione/regolamento`, {
    method: "PUT",
    accessToken,
    body: payload,
  });
}

import {
  hasPermissions,
  type AuthTokensResponse,
  type LeagueSummary,
  type Permission,
  type PermissionContext,
  type SessionUser,
} from "@fantappero/contracts";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import * as authApi from "../api/auth";
import { ApiError } from "../api/client";
import { useSearchParams } from "../router/simpleRouter";
import {
  buildPermissionContext,
  resolveDemoLeagues,
  resolveDemoUser,
  resolveInitialLeagueId,
} from "./demoSession";
import { clearStoredSession, loadStoredSession, saveStoredSession } from "./sessionStorage";

export type AuthContextValue = {
  user: SessionUser | null;
  isAuthenticated: boolean;
  isDemoMode: boolean;
  loading: boolean;
  leagues: readonly LeagueSummary[];
  activeLeagueId: string | null;
  activeLeague: LeagueSummary | null;
  permissionContext: PermissionContext | null;
  setActiveLeagueId: (leagueId: string) => void;
  can: (required: readonly Permission[]) => boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  applySession: (tokens: AuthTokensResponse) => void;
  updateDisplayName: (displayName: string) => void;
};

const AuthContext = createContext<AuthContextValue | null>(null);

export type AuthProviderProps = {
  children: ReactNode;
};

function isDemoPersonaActive(search: string): boolean {
  if (!import.meta.env.DEV) {
    return false;
  }
  const params = new URLSearchParams(search);
  return params.has("persona");
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [searchParams] = useSearchParams();
  const isDemoMode = isDemoPersonaActive(searchParams);
  const demoUser = useMemo(() => resolveDemoUser(searchParams), [searchParams, isDemoMode]);
  const demoLeagues = useMemo(() => resolveDemoLeagues(searchParams), [searchParams, isDemoMode]);

  const [user, setUser] = useState<SessionUser | null>(() => {
    if (isDemoMode) {
      return demoUser;
    }
    return loadStoredSession()?.user ?? null;
  });
  const [loading, setLoading] = useState(() => {
    if (isDemoMode) {
      return false;
    }
    return loadStoredSession() !== null;
  });

  const leagues = isDemoMode ? demoLeagues : [];
  const [activeLeagueId, setActiveLeagueIdState] = useState<string | null>(() =>
    isDemoMode ? resolveInitialLeagueId(searchParams, demoLeagues) : null,
  );

  useEffect(() => {
    if (isDemoMode) {
      setUser(demoUser);
      setLoading(false);
      return;
    }

    const stored = loadStoredSession();
    if (!stored) {
      setUser(null);
      setLoading(false);
      return;
    }

    let cancelled = false;
    authApi
      .fetchMe(stored.accessToken)
      .then((sessionUser) => {
        if (!cancelled) {
          setUser(sessionUser);
        }
      })
      .catch(async () => {
        try {
          const refreshed = await authApi.refresh({ refreshToken: stored.refreshToken });
          if (!cancelled) {
            saveStoredSession({
              accessToken: refreshed.accessToken,
              refreshToken: refreshed.refreshToken,
              user: refreshed.user,
            });
            setUser(refreshed.user);
          }
        } catch {
          if (!cancelled) {
            clearStoredSession();
            setUser(null);
          }
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [isDemoMode, demoUser]);

  const applySession = useCallback((tokens: AuthTokensResponse) => {
    saveStoredSession({
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      user: tokens.user,
    });
    setUser(tokens.user);
  }, []);

  const updateDisplayName = useCallback((displayName: string) => {
    setUser((current) => {
      if (!current) {
        return current;
      }
      const nextUser = { ...current, displayName };
      const stored = loadStoredSession();
      if (stored) {
        saveStoredSession({ ...stored, user: nextUser });
      }
      return nextUser;
    });
  }, []);

  const login = useCallback(
    async (email: string, password: string) => {
      const tokens = await authApi.login({ email, password });
      applySession(tokens);
    },
    [applySession],
  );

  const logout = useCallback(async () => {
    const stored = loadStoredSession();
    clearStoredSession();
    setUser(null);
    if (stored?.refreshToken) {
      try {
        await authApi.logout({ refreshToken: stored.refreshToken });
      } catch {
        // Session already cleared locally.
      }
    }
  }, []);

  const setActiveLeagueId = useCallback((leagueId: string) => {
    setActiveLeagueIdState(leagueId);
  }, []);

  const permissionContext = useMemo(() => {
    if (!user) {
      return null;
    }
    return buildPermissionContext(user, activeLeagueId, leagues);
  }, [user, activeLeagueId, leagues]);

  const activeLeague = permissionContext?.activeLeague ?? null;

  const can = useCallback(
    (required: readonly Permission[]) => {
      if (!permissionContext) {
        return false;
      }
      return hasPermissions(permissionContext, required);
    },
    [permissionContext],
  );

  const value = useMemo<AuthContextValue>(
    () => ({
      user,
      isAuthenticated: user !== null,
      isDemoMode,
      loading,
      leagues,
      activeLeagueId,
      activeLeague,
      permissionContext,
      setActiveLeagueId,
      can,
      login,
      logout,
      applySession,
      updateDisplayName,
    }),
    [
      user,
      isDemoMode,
      loading,
      leagues,
      activeLeagueId,
      activeLeague,
      permissionContext,
      setActiveLeagueId,
      can,
      login,
      logout,
      applySession,
      updateDisplayName,
    ],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
}

export function getApiErrorMessage(error: unknown, fallback: string): string {
  if (error instanceof ApiError) {
    return error.message;
  }
  return fallback;
}

import {
  hasPermissions,
  type AuthTokensResponse,
  type LeagueSummary,
  type Permission,
  type PermissionContext,
  type SessionUser,
} from "@fantappero/contracts";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import * as authApi from "../api/auth";
import { ApiError } from "../api/client";
import { fetchMyLeagues } from "../api/leagues";
import { useSearchParams } from "../router/simpleRouter";
import {
  buildPermissionContext,
  resolveDemoLeagues,
  resolveDemoUser,
  resolveInitialLeagueId,
} from "./demoSession";
import {
  clearStoredActiveLeagueId,
  clearStoredSession,
  loadStoredActiveLeagueId,
  loadStoredSession,
  saveStoredActiveLeagueId,
  saveStoredSession,
} from "./sessionStorage";

export type AuthContextValue = {
  user: SessionUser | null;
  isAuthenticated: boolean;
  isDemoMode: boolean;
  loading: boolean;
  leagues: readonly LeagueSummary[];
  activeLeagueId: string | null;
  activeLeague: LeagueSummary | null;
  permissionContext: PermissionContext | null;
  setActiveLeagueId: (leagueId: string) => void;
  can: (required: readonly Permission[]) => boolean;
  registerLeague: (league: LeagueSummary) => void;
  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  applySession: (tokens: AuthTokensResponse) => void;
  updateDisplayName: (displayName: string) => void;
};

const AuthContext = createContext<AuthContextValue | null>(null);

export type AuthProviderProps = {
  children: ReactNode;
};

function isDemoPersonaActive(search: string | URLSearchParams): boolean {
  if (!import.meta.env.DEV) {
    return false;
  }
  const params = search instanceof URLSearchParams ? search : new URLSearchParams(search);
  return params.has("persona");
}

function resolvePreferredLeagueId(
  leagues: readonly LeagueSummary[],
  currentLeagueId: string | null,
): string | null {
  if (currentLeagueId && leagues.some((league) => league.id === currentLeagueId)) {
    return currentLeagueId;
  }
  return leagues[0]?.id ?? null;
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [searchParams] = useSearchParams();
  const isDemoMode = isDemoPersonaActive(searchParams);
  const demoUser = useMemo(() => resolveDemoUser(searchParams), [searchParams, isDemoMode]);
  const demoLeagues = useMemo(() => resolveDemoLeagues(searchParams), [searchParams, isDemoMode]);

  const [user, setUser] = useState<SessionUser | null>(() => {
    if (isDemoMode) {
      return demoUser;
    }
    return loadStoredSession()?.user ?? null;
  });
  const [loading, setLoading] = useState(() => {
    if (isDemoMode) {
      return false;
    }
    return loadStoredSession() !== null;
  });
  const [leaguesState, setLeaguesState] = useState<LeagueSummary[]>([]);
  const [activeLeagueId, setActiveLeagueIdState] = useState<string | null>(() =>
    isDemoMode ? resolveInitialLeagueId(searchParams, demoLeagues) : loadStoredActiveLeagueId(),
  );
  const leagues = isDemoMode ? demoLeagues : leaguesState;

  useEffect(() => {
    if (isDemoMode) {
      setUser(demoUser);
      setActiveLeagueIdState(resolveInitialLeagueId(searchParams, demoLeagues));
      setLoading(false);
      return;
    }

    const stored = loadStoredSession();
    if (!stored) {
      setUser(null);
      setLeaguesState([]);
      setActiveLeagueIdState(null);
      clearStoredActiveLeagueId();
      setLoading(false);
      return;
    }

    let cancelled = false;
    void (async () => {
      let accessToken = stored.accessToken;
      let sessionUser: SessionUser;
      try {
        sessionUser = await authApi.fetchMe(accessToken);
      } catch {
        try {
          const refreshed = await authApi.refresh({ refreshToken: stored.refreshToken });
          saveStoredSession({
            accessToken: refreshed.accessToken,
            refreshToken: refreshed.refreshToken,
            user: refreshed.user,
          });
          accessToken = refreshed.accessToken;
          sessionUser = refreshed.user;
        } catch {
          if (cancelled) {
            return;
          }
          clearStoredSession();
          clearStoredActiveLeagueId();
          setUser(null);
          setLeaguesState([]);
          setActiveLeagueIdState(null);
          setLoading(false);
          return;
        }
      }

      if (cancelled) {
        return;
      }
      setUser(sessionUser);

      try {
        const memberships = await fetchMyLeagues(accessToken);
        if (cancelled) {
          return;
        }
        setLeaguesState(memberships);
        setActiveLeagueIdState((current) => {
          const nextLeagueId = resolvePreferredLeagueId(
            memberships,
            current ?? loadStoredActiveLeagueId(),
          );
          if (nextLeagueId) {
            saveStoredActiveLeagueId(nextLeagueId);
          } else {
            clearStoredActiveLeagueId();
          }
          return nextLeagueId;
        });
      } catch {
        if (cancelled) {
          return;
        }
        setLeaguesState([]);
        setActiveLeagueIdState(null);
        clearStoredActiveLeagueId();
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [isDemoMode, demoLeagues, demoUser, searchParams]);

  const applySession = useCallback((tokens: AuthTokensResponse) => {
    saveStoredSession({
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      user: tokens.user,
    });
    setUser(tokens.user);
  }, []);

  const updateDisplayName = useCallback((displayName: string) => {
    setUser((current) => {
      if (!current) {
        return current;
      }
      const nextUser = { ...current, displayName };
      const stored = loadStoredSession();
      if (stored) {
        saveStoredSession({ ...stored, user: nextUser });
      }
      return nextUser;
    });
  }, []);

  const login = useCallback(
    async (email: string, password: string) => {
      const tokens = await authApi.login({ email, password });
      applySession(tokens);

      if (isDemoMode) {
        return;
      }
      try {
        const memberships = await fetchMyLeagues(tokens.accessToken);
        setLeaguesState(memberships);
        const nextLeagueId = resolvePreferredLeagueId(memberships, loadStoredActiveLeagueId());
        setActiveLeagueIdState(nextLeagueId);
        if (nextLeagueId) {
          saveStoredActiveLeagueId(nextLeagueId);
        } else {
          clearStoredActiveLeagueId();
        }
      } catch {
        setLeaguesState([]);
        setActiveLeagueIdState(null);
        clearStoredActiveLeagueId();
      }
    },
    [applySession, isDemoMode],
  );

  const logout = useCallback(async () => {
    const stored = loadStoredSession();
    clearStoredSession();
    clearStoredActiveLeagueId();
    setUser(null);
    setLeaguesState([]);
    setActiveLeagueIdState(null);
    if (stored?.refreshToken) {
      try {
        await authApi.logout({ refreshToken: stored.refreshToken });
      } catch {
        // Session already cleared locally.
      }
    }
  }, []);

  const setActiveLeagueId = useCallback((leagueId: string) => {
    setActiveLeagueIdState(leagueId);
    if (!isDemoMode) {
      saveStoredActiveLeagueId(leagueId);
    }
  }, [isDemoMode]);

  const registerLeague = useCallback(
    (league: LeagueSummary) => {
      if (isDemoMode) {
        return;
      }
      setLeaguesState((current) => {
        const existingIndex = current.findIndex((row) => row.id === league.id);
        if (existingIndex >= 0) {
          const next = [...current];
          next[existingIndex] = league;
          return next;
        }
        return [...current, league];
      });
      setActiveLeagueIdState(league.id);
      saveStoredActiveLeagueId(league.id);
    },
    [isDemoMode],
  );

  const permissionContext = useMemo(() => {
    if (!user) {
      return null;
    }
    return buildPermissionContext(user, activeLeagueId, leagues);
  }, [user, activeLeagueId, leagues]);

  const activeLeague = permissionContext?.activeLeague ?? null;

  const can = useCallback(
    (required: readonly Permission[]) => {
      if (!permissionContext) {
        return false;
      }
      return hasPermissions(permissionContext, required);
    },
    [permissionContext],
  );

  const value = useMemo<AuthContextValue>(
    () => ({
      user,
      isAuthenticated: user !== null,
      isDemoMode,
      loading,
      leagues,
      activeLeagueId,
      activeLeague,
      permissionContext,
      setActiveLeagueId,
      can,
      registerLeague,
      login,
      logout,
      applySession,
      updateDisplayName,
    }),
    [
      user,
      isDemoMode,
      loading,
      leagues,
      activeLeagueId,
      activeLeague,
      permissionContext,
      setActiveLeagueId,
      can,
      registerLeague,
      login,
      logout,
      applySession,
      updateDisplayName,
    ],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
}

export function getApiErrorMessage(error: unknown, fallback: string): string {
  if (error instanceof ApiError) {
    return error.message;
  }
  return fallback;
}

import type { Permission } from "@fantappero/contracts";
import { UiStatePanel } from "@fantappero/ui";
import { type ReactNode } from "react";
import { useAuth } from "../auth/AuthContext";

export type RequirePermissionsProps = {
  required: readonly Permission[];
  children: ReactNode;
};

/** Client-side gate — server remains authoritative (EP02-03). */
export function RequirePermissions({ required, children }: RequirePermissionsProps) {
  const { can, user } = useAuth();

  if (!user) {
    return (
      <UiStatePanel
        state="empty"
        title="Accesso richiesto"
        message="Accedi per visualizzare questa sezione."
        testId="route-unauthenticated"
      />
    );
  }

  if (!can(required)) {
    return (
      <UiStatePanel
        state="forbidden"
        title="Permessi insufficienti"
        message="Non hai accesso a questa sezione. Contatta l'amministratore di lega se pensi sia un errore."
        testId="route-forbidden"
      />
    );
  }

  return <>{children}</>;
}

export type RequireGlobalOperatorProps = {
  children: ReactNode;
};

export function RequireGlobalOperator({ children }: RequireGlobalOperatorProps) {
  const { user } = useAuth();

  if (!user || user.globalRole !== "global_operator") {
    return (
      <UiStatePanel
        state="forbidden"
        title="Area riservata"
        message="Il pannello operatore globale è accessibile solo allo staff piattaforma."
        testId="route-forbidden"
      />
    );
  }

  return <>{children}</>;
}

import { hasPermissions, type Permission } from "@fantappero/contracts";
import { UiStatePanel } from "@fantappero/ui";
import { type ReactNode, useEffect, useMemo } from "react";
import { useAuth } from "../auth/AuthContext";
import { useLocation } from "../router/simpleRouter";

export type RequirePermissionsProps = {
  required: readonly Permission[];
  children: ReactNode;
};

/** Client-side gate — server remains authoritative (EP02-03). */
export function RequirePermissions({ required, children }: RequirePermissionsProps) {
  const { can, user, loading, leagues, activeLeagueId, setActiveLeagueId } = useAuth();
  const { search } = useLocation();

  const requestedLeagueId = useMemo(
    () => new URLSearchParams(search).get("leagueId"),
    [search],
  );

  const requestedLeague = useMemo(() => {
    if (!requestedLeagueId) {
      return null;
    }
    return leagues.find((league) => league.id === requestedLeagueId) ?? null;
  }, [leagues, requestedLeagueId]);

  const requestedLeagueAllowed = useMemo(() => {
    if (!user || !requestedLeague) {
      return false;
    }
    return hasPermissions({ user, activeLeague: requestedLeague }, required);
  }, [required, requestedLeague, user]);

  const activeLeagueAllowed = can(required);
  const isAllowed = requestedLeagueId ? requestedLeagueAllowed : activeLeagueAllowed;

  const fallbackLeagueId = useMemo(() => {
    if (!user || requestedLeagueId) {
      return null;
    }
    return (
      leagues.find((league) => hasPermissions({ user, activeLeague: league }, required))?.id ?? null
    );
  }, [leagues, requestedLeagueId, required, user]);

  useEffect(() => {
    if (!user || loading) {
      return;
    }

    if (requestedLeagueId && requestedLeagueAllowed && requestedLeagueId !== activeLeagueId) {
      setActiveLeagueId(requestedLeagueId);
      return;
    }

    if (!requestedLeagueId && !isAllowed && fallbackLeagueId && fallbackLeagueId !== activeLeagueId) {
      setActiveLeagueId(fallbackLeagueId);
    }
  }, [
    activeLeagueId,
    fallbackLeagueId,
    isAllowed,
    loading,
    requestedLeagueAllowed,
    requestedLeagueId,
    setActiveLeagueId,
    user,
  ]);

  if (!user) {
    return (
      <UiStatePanel
        state="empty"
        title="Accesso richiesto"
        message="Accedi per visualizzare questa sezione."
        testId="route-unauthenticated"
      />
    );
  }

  if (loading) {
    return (
      <UiStatePanel
        state="loading"
        title="Verifica permessi"
        message="Controllo autorizzazioni in corso…"
        testId="route-loading"
      />
    );
  }

  if (!isAllowed) {
    if (!requestedLeagueId && fallbackLeagueId && fallbackLeagueId !== activeLeagueId) {
      return (
        <UiStatePanel
          state="loading"
          title="Selezione lega"
          message="Seleziono una lega in cui hai i permessi richiesti…"
          testId="route-switching-league"
        />
      );
    }

    return (
      <UiStatePanel
        state="forbidden"
        title="Permessi insufficienti"
        message="Non hai accesso a questa sezione. Contatta l'amministratore di lega se pensi sia un errore."
        testId="route-forbidden"
      />
    );
  }

  return <>{children}</>;
}

export type RequireGlobalOperatorProps = {
  children: ReactNode;
};

export function RequireGlobalOperator({ children }: RequireGlobalOperatorProps) {
  const { user } = useAuth();

  if (!user || user.globalRole !== "global_operator") {
    return (
      <UiStatePanel
        state="forbidden"
        title="Area riservata"
        message="Il pannello operatore globale è accessibile solo allo staff piattaforma."
        testId="route-forbidden"
      />
    );
  }

  return <>{children}</>;
}

import {
  type LeagueSummary,
  type PermissionContext,
  type SessionUser,
} from "@fantappero/contracts";

/** Demo leagues — replaced by API in EP02-03+. */
export const DEMO_LEAGUES: readonly LeagueSummary[] = [
  { id: "lega-demo", name: "Lega Demo", role: "member" },
  { id: "lega-admin", name: "Lega Amici", role: "league_admin" },
];

export const DEMO_MEMBER: SessionUser = {
  id: "user-demo",
  displayName: "Marco Rossi",
  globalRole: "member",
};

export const DEMO_OPERATOR: SessionUser = {
  id: "op-demo",
  displayName: "Operatore Piattaforma",
  globalRole: "global_operator",
};

export function buildPermissionContext(
  user: SessionUser,
  activeLeagueId: string | null,
  leagues: readonly LeagueSummary[] = DEMO_LEAGUES,
): PermissionContext {
  const activeLeague = leagues.find((league) => league.id === activeLeagueId) ?? null;
  return { user, activeLeague };
}

/**
 * Query param `?persona=operator|admin` switches mock session for local QA.
 * Production session comes from EP02-03 auth API.
 */
export function resolveDemoUser(search: string): SessionUser {
  const params = new URLSearchParams(search);
  const persona = params.get("persona");
  if (persona === "operator") {
    return DEMO_OPERATOR;
  }
  return DEMO_MEMBER;
}

export function resolveDemoLeagues(search: string): readonly LeagueSummary[] {
  const params = new URLSearchParams(search);
  if (params.get("persona") === "admin") {
    return DEMO_LEAGUES.map((league) =>
      league.id === "lega-admin" ? { ...league, role: "league_admin" as const } : league,
    );
  }
  return DEMO_LEAGUES;
}

export function resolveInitialLeagueId(
  search: string,
  leagues: readonly LeagueSummary[],
): string | null {
  const params = new URLSearchParams(search);
  if (params.get("persona") === "admin") {
    return leagues.find((league) => league.role === "league_admin")?.id ?? leagues[0]?.id ?? null;
  }
  return leagues[0]?.id ?? null;
}

import {
  type LeagueSummary,
  type PermissionContext,
  type SessionUser,
} from "@fantappero/contracts";

/** Demo leagues — replaced by API in EP02-03+. */
export const DEMO_LEAGUES: readonly LeagueSummary[] = [
  { id: "lega-demo", name: "Lega Demo", role: "member" },
  { id: "lega-admin", name: "Lega Amici", role: "league_admin" },
];

export const DEMO_MEMBER: SessionUser = {
  id: "user-demo",
  displayName: "Marco Rossi",
  globalRole: "member",
};

export const DEMO_OPERATOR: SessionUser = {
  id: "op-demo",
  displayName: "Operatore Piattaforma",
  globalRole: "global_operator",
};

function asSearchParams(search: string | URLSearchParams): URLSearchParams {
  if (search instanceof URLSearchParams) {
    return search;
  }
  return new URLSearchParams(search);
}

export function buildPermissionContext(
  user: SessionUser,
  activeLeagueId: string | null,
  leagues: readonly LeagueSummary[] = DEMO_LEAGUES,
): PermissionContext {
  const activeLeague = leagues.find((league) => league.id === activeLeagueId) ?? null;
  return { user, activeLeague };
}

/**
 * Query param `?persona=operator|admin` switches mock session for local QA.
 * Production session comes from EP02-03 auth API.
 */
export function resolveDemoUser(search: string | URLSearchParams): SessionUser {
  const params = asSearchParams(search);
  const persona = params.get("persona");
  if (persona === "operator") {
    return DEMO_OPERATOR;
  }
  return DEMO_MEMBER;
}

export function resolveDemoLeagues(search: string | URLSearchParams): readonly LeagueSummary[] {
  const params = asSearchParams(search);
  if (params.get("persona") === "admin") {
    return DEMO_LEAGUES.map((league) =>
      league.id === "lega-admin" ? { ...league, role: "league_admin" as const } : league,
    );
  }
  return DEMO_LEAGUES.map((league) => ({ ...league, role: "member" as const }));
}

export function resolveInitialLeagueId(
  search: string | URLSearchParams,
  leagues: readonly LeagueSummary[],
): string | null {
  const params = asSearchParams(search);
  if (params.get("persona") === "admin") {
    return leagues.find((league) => league.role === "league_admin")?.id ?? leagues[0]?.id ?? null;
  }
  return leagues[0]?.id ?? null;
}

import type { SessionUser } from "@fantappero/contracts";

const ACCESS_TOKEN_KEY = "fantappero.accessToken";
const REFRESH_TOKEN_KEY = "fantappero.refreshToken";
const USER_KEY = "fantappero.sessionUser";

export type StoredSession = {
  accessToken: string;
  refreshToken: string;
  user: SessionUser;
};

export function loadStoredSession(): StoredSession | null {
  if (typeof sessionStorage === "undefined") {
    return null;
  }
  const accessToken = sessionStorage.getItem(ACCESS_TOKEN_KEY);
  const refreshToken = sessionStorage.getItem(REFRESH_TOKEN_KEY);
  const userRaw = sessionStorage.getItem(USER_KEY);
  if (!accessToken || !refreshToken || !userRaw) {
    return null;
  }
  try {
    return {
      accessToken,
      refreshToken,
      user: JSON.parse(userRaw) as SessionUser,
    };
  } catch {
    clearStoredSession();
    return null;
  }
}

export function saveStoredSession(session: StoredSession): void {
  sessionStorage.setItem(ACCESS_TOKEN_KEY, session.accessToken);
  sessionStorage.setItem(REFRESH_TOKEN_KEY, session.refreshToken);
  sessionStorage.setItem(USER_KEY, JSON.stringify(session.user));
}

export function clearStoredSession(): void {
  sessionStorage.removeItem(ACCESS_TOKEN_KEY);
  sessionStorage.removeItem(REFRESH_TOKEN_KEY);
  sessionStorage.removeItem(USER_KEY);
}

