            <Link to="/leghe">
              <Button type="button" variant="ghost">
                Annulla
              </Button>
            </Link>
          </div>
        </form>
      ) : null}

      {!loadingCatalog && catalogError ? (
        <Button variant="ghost" onClick={() => void loadCatalog()} data-testid="create-league-retry">
          Ricarica campionati
        </Button>
      ) : null}
    </PageContainer>
  );
}

import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it, vi } from "vitest";
import { AuthProvider } from "../auth/AuthContext";
import { AppRoutes } from "../routes";
import { MemoryRouter } from "../router/simpleRouter";

vi.mock("../api/auth", () => ({
  login: vi.fn(),
  register: vi.fn(),
  forgotPassword: vi.fn(),
  resetPassword: vi.fn(),
  verifyEmail: vi.fn(),
  fetchMe: vi.fn(),
  refresh: vi.fn(),
  logout: vi.fn(),
  resendVerification: vi.fn(),
}));

vi.mock("../api/leagues", () => ({
  fetchCompetitions: vi.fn(),
  fetchMyLeagues: vi.fn(),
  createLeague: vi.fn(),
  fetchLeagueAdminPanel: vi.fn(),
  updateLeagueRules: vi.fn(),
}));

function renderRoute(path: string) {
  return renderToStaticMarkup(
    createElement(MemoryRouter, {
      initialEntries: [path],
      children: createElement(AuthProvider, {
        children: createElement(AppRoutes),
      }),
    }),
  );
}

describe("EP03-02 league admin page", () => {
  it("renders positive flow in demo admin mode", () => {
    const html = renderRoute("/lega/amministrazione?persona=admin");
    expect(html).toContain('data-testid="league-admin-form"');
    expect(html).toContain("Preset regolamento");
    expect(html).toContain("Partecipanti");
    expect(html).toContain("Crediti iniziali");
    expect(html).toContain("Salva configurazione");
  });

  it("renders empty state", () => {
    const html = renderRoute("/lega/amministrazione?persona=admin&stato=empty");
    expect(html).toContain('data-testid="league-admin-empty"');
    expect(html).toContain("Nessuna lega selezionata");
  });

  it("renders error state", () => {
    const html = renderRoute("/lega/amministrazione?persona=admin&stato=error");
    expect(html).toContain('data-testid="league-admin-error"');
    expect(html).toContain("Errore di caricamento");
  });

  it("blocks non-admin users", () => {
    const html = renderRoute("/lega/amministrazione?persona=member");
    expect(html).toContain('data-testid="route-forbidden"');
    expect(html).toContain("Permessi insufficienti");
  });
});

import type { LeagueRules, UpdateLeagueRulesRequest } from "@fantappero/contracts";
import {
  Breadcrumb,
  Button,
  Input,
  PageContainer,
  Select,
  UiStatePanel,
} from "@fantappero/ui";
import { type FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import { fetchLeagueAdminPanel, updateLeagueRules } from "../api/leagues";
import { getApiErrorMessage, useAuth } from "../auth/AuthContext";
import { loadStoredSession } from "../auth/sessionStorage";
import { useLocation } from "../router/simpleRouter";
import { parseWireframeStateFromSearch } from "../wireframes/useWireframeState";

const DEMO_RULES: LeagueRules = {
  presetName: "standard",
  participantCount: 8,
  participantMin: 4,
  participantMax: 10,
  roster: {
    rosterSize: 35,
    goalkeepers: 3,
    defenders: 11,
    midfielders: 11,
    forwards: 10,
  },
  totalCredits: 1000,
  options: {
    allowTrades: true,
    allowManualInvites: true,
  },
};

function toParticipantOptions(min: number, max: number): Array<{ value: string; label: string }> {
  const options: Array<{ value: string; label: string }> = [];
  for (let value = min; value <= max; value += 1) {
    options.push({ value: String(value), label: String(value) });
  }
  return options;
}

function buildPayloadFromRules(rules: LeagueRules): UpdateLeagueRulesRequest {
  return {
    presetName: rules.presetName,
    participantCount: rules.participantCount,
    roster: { ...rules.roster },
    totalCredits: rules.totalCredits,
    options: { ...rules.options },
  };
}

/** Configurazione regolamento lega prima dell'avvio stagione (EP03-02). */
export function LeagueAdminPage() {
  const { isDemoMode, activeLeagueId } = useAuth();
  const { search } = useLocation();
  const demoState = isDemoMode ? parseWireframeStateFromSearch(search) : null;

  const [rules, setRules] = useState<LeagueRules | null>(() =>
    isDemoMode && demoState === "success" ? DEMO_RULES : null,
  );
  const [loading, setLoading] = useState(() => (isDemoMode ? demoState === "loading" : true));
  const [loadError, setLoadError] = useState<string | null>(() =>
    isDemoMode && demoState === "error" ? "Impossibile caricare il regolamento (demo)." : null,
  );
  const [saveError, setSaveError] = useState<string | null>(null);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [saving, setSaving] = useState(false);

  const loadPanel = useCallback(async () => {
    setSaveSuccess(false);
    setSaveError(null);
    if (isDemoMode) {
      if (demoState === "loading") {
        setLoading(true);
        setRules(null);
        setLoadError(null);
        return;
      }
      if (demoState === "error") {
        setLoading(false);
        setRules(null);
        setLoadError("Impossibile caricare il regolamento (demo).");
        return;
      }
      if (demoState === "empty") {
        setLoading(false);
        setRules(null);
        setLoadError(null);
        return;
      }
      setLoading(false);
      setRules(DEMO_RULES);
      setLoadError(null);
      return;
    }

    if (!activeLeagueId) {
      setLoading(false);
      setRules(null);
      setLoadError(null);
      return;
    }

    const stored = loadStoredSession();
    if (!stored?.accessToken) {
      setLoading(false);
      setRules(null);
      setLoadError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }

    setLoading(true);
    setLoadError(null);
    try {
      const panel = await fetchLeagueAdminPanel(stored.accessToken, activeLeagueId);
      setRules(panel.rules);
    } catch (error) {
      setLoadError(getApiErrorMessage(error, "Impossibile caricare il regolamento."));
      setRules(null);
    } finally {
      setLoading(false);
    }
  }, [activeLeagueId, demoState, isDemoMode]);

  useEffect(() => {
    void loadPanel();
  }, [loadPanel]);

  const participantOptions = useMemo(
    () =>
      rules
        ? toParticipantOptions(rules.participantMin, rules.participantMax)
        : toParticipantOptions(DEMO_RULES.participantMin, DEMO_RULES.participantMax),
    [rules],
  );

  function updateLocalRules(next: Partial<LeagueRules>) {
    setRules((current: LeagueRules | null) => {
      if (!current) {
        return current;
      }
      return { ...current, ...next };
    });
  }

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!rules) {
      return;
    }
    setSaveError(null);
    setSaveSuccess(false);

    if (isDemoMode) {
      setSaveSuccess(true);
      return;
    }

    if (!activeLeagueId) {
      setSaveError("Seleziona una lega prima di salvare il regolamento.");
      return;
    }

    const stored = loadStoredSession();
    if (!stored?.accessToken) {
      setSaveError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }

    setSaving(true);
    try {
      const saved = await updateLeagueRules(
        stored.accessToken,
        activeLeagueId,
        buildPayloadFromRules(rules),
      );
      setRules(saved);
      setSaveSuccess(true);
    } catch (error) {
      setSaveError(getApiErrorMessage(error, "Impossibile salvare il regolamento."));
    } finally {
      setSaving(false);
    }
  }

  return (
    <PageContainer
      title="Amministrazione lega"
      header={
        <Breadcrumb
          items={[
            { label: "Leghe", href: "/leghe" },
            { label: "Amministrazione" },
          ]}
        />
      }
    >
      {loading ? (
        <UiStatePanel
          state="loading"
          title="Caricamento configurazione"
          message="Recupero regolamento e opzioni in corso…"
          testId="league-admin-loading"
        />
      ) : null}

      {!loading && loadError ? (
        <UiStatePanel
          state="error"
          title="Errore di caricamento"
          message={loadError}
          testId="league-admin-error"
        />
      ) : null}

      {!loading && !loadError && !rules ? (
        <UiStatePanel
          state="empty"
          title="Nessuna lega selezionata"
          message="Seleziona una lega e imposta il regolamento prima dell'avvio."
          testId="league-admin-empty"
        />
      ) : null}

      {!loading && !loadError && rules ? (
        <form data-testid="league-admin-form" onSubmit={(event) => void onSubmit(event)}>
          <Select
            label="Preset regolamento"
            name="preset"
            value={rules.presetName}
            onChange={() => undefined}
            options={[{ value: "standard", label: "Standard" }]}
            disabled
          />

          <Select
            label="Partecipanti"
            name="participants"
            value={String(rules.participantCount)}
            onChange={(event) =>
              updateLocalRules({ participantCount: Number(event.target.value) })
            }
            options={participantOptions}
          />

          <Input
            label="Crediti iniziali"
            name="credits"
            type="number"
            min={1}
            value={String(rules.totalCredits)}
            onChange={(event) =>
              updateLocalRules({ totalCredits: Number(event.target.value) || 0 })
            }
          />

          <fieldset data-testid="league-admin-roster" style={{ marginBottom: "1rem" }}>
            <legend>Rosa standard (fissa)</legend>
            <p>{`${rules.roster.rosterSize} giocatori: ${rules.roster.goalkeepers}P-${rules.roster.defenders}D-${rules.roster.midfielders}C-${rules.roster.forwards}A`}</p>
          </fieldset>

          <fieldset data-testid="league-admin-options" style={{ marginBottom: "1rem" }}>
            <legend>Opzioni lega</legend>
            <label>
              <input
                type="checkbox"
                checked={rules.options.allowTrades}
                onChange={(event) =>
                  updateLocalRules({
                    options: {
                      ...rules.options,
                      allowTrades: event.target.checked,
                    },
                  })
                }
              />{" "}
              Abilita scambi
            </label>
            <label>
              <input
                type="checkbox"
                checked={rules.options.allowManualInvites}
                onChange={(event) =>
                  updateLocalRules({
                    options: {
                      ...rules.options,
                      allowManualInvites: event.target.checked,
                    },
                  })
                }
              />{" "}
              Abilita inviti manuali
            </label>
          </fieldset>

          {saveError ? (
            <UiStatePanel
              state="error"
              title="Configurazione non salvata"
              message={saveError}
              testId="league-admin-save-error"
            />
          ) : null}

          {saveSuccess ? (
            <UiStatePanel
              state="success"
              title="Configurazione salvata"
              message="Regolamento aggiornato con preset Standard."
              testId="league-admin-save-success"
            />
          ) : null}

          <div className="fa-ds-showcase__row">
            <Button type="submit" variant="primary" disabled={saving} data-testid="league-admin-submit">
              {saving ? "Salvataggio…" : "Salva configurazione"}
            </Button>
            {loadError ? (
              <Button type="button" variant="ghost" onClick={() => void loadPanel()}>
                Riprova
              </Button>
            ) : null}
          </div>
        </form>
      ) : null}
    </PageContainer>
  );
}

import type { LeagueSummary } from "@fantappero/contracts";
import {
  Breadcrumb,
  Button,
  Card,
  CardBody,
  CardHeader,
  PageContainer,
  UiStatePanel,
} from "@fantappero/ui";
import { useCallback, useEffect, useState } from "react";
import { fetchMyLeagues } from "../api/leagues";
import { getApiErrorMessage, useAuth } from "../auth/AuthContext";
import { loadStoredSession } from "../auth/sessionStorage";
import { Link, useLocation } from "../router/simpleRouter";
import { parseWireframeStateFromSearch } from "../wireframes/useWireframeState";

const DEMO_LEAGUES: LeagueSummary[] = [
  { id: "demo-league-1", name: "Lega Demo", role: "league_admin" },
];

function leagueStateLabel(state: string | undefined): string {
  if (state === "draft") {
    return "Bozza";
  }
  if (state === "active") {
    return "Attiva";
  }
  return "—";
}

/** Elenco leghe dell'utente con stato vuoto e azione di creazione (EP03-01). */
export function LeaguesPage() {
  const { isDemoMode } = useAuth();
  const { search } = useLocation();
  const demoState = isDemoMode ? parseWireframeStateFromSearch(search) : null;
  const [leagues, setLeagues] = useState<LeagueSummary[]>(() =>
    isDemoMode && demoState !== "empty" ? DEMO_LEAGUES : [],
  );
  const [loading, setLoading] = useState(() =>
    isDemoMode ? demoState === "loading" : true,
  );
  const [loadError, setLoadError] = useState<string | null>(() =>
    isDemoMode && demoState === "error" ? "Impossibile caricare le leghe (demo)." : null,
  );

  const loadLeagues = useCallback(async () => {
    if (isDemoMode) {
      if (demoState === "loading") {
        setLoading(true);
        setLoadError(null);
        setLeagues([]);
        return;
      }
      if (demoState === "error") {
        setLoading(false);
        setLoadError("Impossibile caricare le leghe (demo).");
        setLeagues([]);
        return;
      }
      if (demoState === "empty") {
        setLoading(false);
        setLoadError(null);
        setLeagues([]);
        return;
      }
      setLeagues(DEMO_LEAGUES);
      setLoading(false);
      return;
    }

    const stored = loadStoredSession();
    if (!stored?.accessToken) {
      setLoadError("Sessione non disponibile. Accedi di nuovo.");
      setLoading(false);
      return;
    }

    setLoading(true);
    setLoadError(null);
    try {
      const rows = await fetchMyLeagues(stored.accessToken);
      setLeagues(rows);
    } catch (error) {
      setLoadError(getApiErrorMessage(error, "Impossibile caricare le leghe."));
    } finally {
      setLoading(false);
    }
  }, [demoState, isDemoMode]);

  useEffect(() => {
    void loadLeagues();
  }, [loadLeagues]);

  return (
    <PageContainer
      title="Le tue leghe"
      header={<Breadcrumb items={[{ label: "Leghe" }]} />}
    >
      {loading ? (
        <UiStatePanel
          state="loading"
          title="Caricamento leghe"
          message="Recupero delle leghe in corso…"
          testId="leagues-loading"
        />
      ) : null}

      {!loading && loadError ? (
        <UiStatePanel
          state="error"
          title="Errore di caricamento"
          message={loadError}
          testId="leagues-error"
        />
      ) : null}

      {!loading && !loadError && leagues.length === 0 ? (
        <UiStatePanel
          state="empty"
          title="Nessuna lega"
          message="Non partecipi ancora a nessuna lega privata. Creane una per iniziare la configurazione."
          testId="leagues-empty"
        />
      ) : null}

      {!loading && !loadError && leagues.length > 0 ? (
        <section data-testid="leagues-list">
          <ul className="fa-league-list">
            {leagues.map((league) => (
              <li key={league.id} className="fa-league-list__item">
                <Card>
                  <CardHeader>{league.name}</CardHeader>
                  <CardBody>
                    <p>
                      Ruolo:{" "}
                      {league.role === "league_admin" ? "Amministratore" : "Partecipante"}
                    </p>
                    <p>Stato: {leagueStateLabel(undefined)}</p>
                  </CardBody>
                </Card>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      <div className="fa-ds-showcase__row" style={{ marginTop: "1rem" }}>
        <Link to="/leghe/crea">
          <Button variant="secondary" data-testid="leagues-create-link">
            Crea lega
          </Button>
        </Link>
        {!loading && loadError ? (
          <Button variant="ghost" onClick={() => void loadLeagues()} data-testid="leagues-retry">
            Ricarica
          </Button>
        ) : null}
      </div>
    </PageContainer>
  );
}

