"""Validation rules for league creation (EP03-01)."""

from __future__ import annotations

from datetime import UTC, datetime
from uuid import UUID

from auth.exceptions import ValidationAuthError

_LEAGUE_NAME_MAX_LENGTH = 120
_MIN_COMPETITIONS = 3
_SEASON_YEAR_MIN = 2020


def validate_league_name(name: str) -> str:
    cleaned = name.strip()
    if not cleaned:
        raise ValidationAuthError("Inserisci un nome per la lega.", code="invalid_league_name")
    if len(cleaned) > _LEAGUE_NAME_MAX_LENGTH:
        raise ValidationAuthError(
            "Il nome della lega è troppo lungo.",
            code="invalid_league_name",
        )
    return cleaned


def validate_season_year(season_year: int) -> int:
    max_year = datetime.now(UTC).year + 1
    if season_year < _SEASON_YEAR_MIN or season_year > max_year:
        raise ValidationAuthError(
            "Seleziona una stagione valida.",
            code="invalid_season_year",
        )
    return season_year


def validate_competition_ids(competition_ids: list[UUID]) -> list[UUID]:
    if len(competition_ids) != len(set(competition_ids)):
        raise ValidationAuthError(
            "Seleziona ogni campionato una sola volta.",
            code="duplicate_competitions",
        )
    if len(competition_ids) < _MIN_COMPETITIONS:
        raise ValidationAuthError(
            f"Seleziona almeno {_MIN_COMPETITIONS} campionati.",
            code="insufficient_competitions",
        )
    return competition_ids

"""Validation rules for league creation and regulation configuration."""

from __future__ import annotations

from datetime import UTC, datetime
from uuid import UUID

from auth.exceptions import ValidationAuthError

_LEAGUE_NAME_MAX_LENGTH = 120
_MIN_COMPETITIONS = 3
_SEASON_YEAR_MIN = 2020
STANDARD_PRESET_NAME = "standard"
MIN_PARTICIPANTS = 4
MAX_PARTICIPANTS = 10
STANDARD_PARTICIPANT_COUNT = 8
STANDARD_ROSTER_SIZE = 35
STANDARD_GOALKEEPERS = 3
STANDARD_DEFENDERS = 11
STANDARD_MIDFIELDERS = 11
STANDARD_FORWARDS = 10
STANDARD_TOTAL_CREDITS = 1000


def validate_league_name(name: str) -> str:
    cleaned = name.strip()
    if not cleaned:
        raise ValidationAuthError("Inserisci un nome per la lega.", code="invalid_league_name")
    if len(cleaned) > _LEAGUE_NAME_MAX_LENGTH:
        raise ValidationAuthError(
            "Il nome della lega è troppo lungo.",
            code="invalid_league_name",
        )
    return cleaned


def validate_season_year(season_year: int) -> int:
    max_year = datetime.now(UTC).year + 1
    if season_year < _SEASON_YEAR_MIN or season_year > max_year:
        raise ValidationAuthError(
            "Seleziona una stagione valida.",
            code="invalid_season_year",
        )
    return season_year


def validate_competition_ids(competition_ids: list[UUID]) -> list[UUID]:
    if len(competition_ids) != len(set(competition_ids)):
        raise ValidationAuthError(
            "Seleziona ogni campionato una sola volta.",
            code="duplicate_competitions",
        )
    if len(competition_ids) < _MIN_COMPETITIONS:
        raise ValidationAuthError(
            f"Seleziona almeno {_MIN_COMPETITIONS} campionati.",
            code="insufficient_competitions",
        )
    return competition_ids


def validate_preset_name(preset_name: str) -> str:
    cleaned = preset_name.strip().lower()
    if cleaned != STANDARD_PRESET_NAME:
        raise ValidationAuthError(
            "È disponibile solo il preset Standard.",
            code="invalid_rules_preset",
        )
    return cleaned


def validate_participant_count(participant_count: int) -> int:
    if participant_count < MIN_PARTICIPANTS or participant_count > MAX_PARTICIPANTS:
        raise ValidationAuthError(
            f"Il numero partecipanti deve essere tra {MIN_PARTICIPANTS} e {MAX_PARTICIPANTS}.",
            code="invalid_participant_count",
        )
    return participant_count


def validate_total_credits(total_credits: int) -> int:
    if total_credits <= 0:
        raise ValidationAuthError(
            "I crediti devono essere maggiori di zero.",
            code="invalid_total_credits",
        )
    return total_credits


def validate_standard_roster(
    *,
    roster_size: int,
    goalkeepers: int,
    defenders: int,
    midfielders: int,
    forwards: int,
) -> None:
    if roster_size != STANDARD_ROSTER_SIZE:
        raise ValidationAuthError(
            f"La rosa deve contenere esattamente {STANDARD_ROSTER_SIZE} giocatori.",
            code="invalid_roster_size",
        )
    if (
        goalkeepers != STANDARD_GOALKEEPERS
        or defenders != STANDARD_DEFENDERS
        or midfielders != STANDARD_MIDFIELDERS
        or forwards != STANDARD_FORWARDS
    ):
        raise ValidationAuthError(
            "La composizione rosa deve essere 3P-11D-11C-10A.",
            code="invalid_roster_distribution",
        )
    if goalkeepers + defenders + midfielders + forwards != roster_size:
        raise ValidationAuthError(
            "La somma dei ruoli deve coincidere con la dimensione della rosa.",
            code="invalid_roster_distribution",
        )

"""HTTP routes for the live/ascending auction mode (EP08-09).

Distinct path prefix (``/mercato/asta-live/...``) from the sealed-bid
``/mercato/asta/...`` router — the two are independent, never share a route.
"""

from __future__ import annotations

from uuid import UUID

from fastapi import APIRouter, Depends, status
from fastapi.responses import JSONResponse
from sqlalchemy.orm import Session

from auth.dependencies import get_db_session
from auth.exceptions import AuthError
from authorization.context import LeagueAccess
from authorization.dependencies import require_league_permissions
from database.enums import Permission
from market.live_authorization import require_live_session_operator
from market.live_schemas import (
    ConfigureLiveAuctionSessionRequest,
    CreateLiveAuctionSessionRequest,
    LiveAuctionSessionResponse,
    LiveLotListResponse,
    LiveLotResponse,
    LiveLotStateResponse,
    NominateLotRequest,
    PlaceRaiseRequest,
    ResolveSwapRequest,
)
from market.live_service import LiveMarketService

router = APIRouter(prefix="/leagues", tags=["market-live"])


def _error_response(exc: AuthError) -> JSONResponse:
    return JSONResponse(
        status_code=status.HTTP_400_BAD_REQUEST,
        content={"message": exc.message, "code": exc.code},
    )


def get_live_market_service(session: Session = Depends(get_db_session)) -> LiveMarketService:
    return LiveMarketService(session)


@router.post(
    "/{league_id}/mercato/asta-live/sessioni",
    response_model=LiveAuctionSessionResponse,
    status_code=status.HTTP_201_CREATED,
)
def create_live_auction_session(
    body: CreateLiveAuctionSessionRequest,
    league_access: LeagueAccess = Depends(require_league_permissions(Permission.MARKET_MANAGE)),
    service: LiveMarketService = Depends(get_live_market_service),
) -> LiveAuctionSessionResponse | JSONResponse:
    """Create a live-auction session for the league's initial auction (admin)."""
    try:
        return service.create_session(league_access, body)
    except AuthError as exc:
        return _error_response(exc)


@router.put(
    "/{league_id}/mercato/asta-live/sessioni/{session_id}/configurazione",
    response_model=LiveAuctionSessionResponse,
)
def configure_live_auction_session(
    session_id: UUID,
    body: ConfigureLiveAuctionSessionRequest,
    league_access: LeagueAccess = Depends(require_league_permissions(Permission.MARKET_MANAGE)),
    service: LiveMarketService = Depends(get_live_market_service),
) -> LiveAuctionSessionResponse | JSONResponse:
    """Reconfigure increments/timers/operator/queue while still scheduled (admin)."""
    try:
        return service.configure_session(league_access, session_id, body)
    except AuthError as exc:
        return _error_response(exc)


@router.get(
    "/{league_id}/mercato/asta-live/sessioni",
    response_model=list[LiveAuctionSessionResponse],
)
def list_live_auction_sessions(
    league_access: LeagueAccess = Depends(require_league_permissions(Permission.MARKET_VIEW)),
    service: LiveMarketService = Depends(get_live_market_service),
) -> list[LiveAuctionSessionResponse]:
    """List live-auction sessions for the league."""
    return service.list_sessions(league_access)


@router.get(
    "/{league_id}/mercato/asta-live/sessioni/{session_id}",
    response_model=LiveAuctionSessionResponse,
)
def get_live_auction_session(
    session_id: UUID,
    league_access: LeagueAccess = Depends(require_league_permissions(Permission.MARKET_VIEW)),
    service: LiveMarketService = Depends(get_live_market_service),
) -> LiveAuctionSessionResponse | JSONResponse:
    try:
        return service.get_session(league_access, session_id)
    except AuthError as exc:
