class LiveRaiseResponse(ApiModel): id: str lot_id: str = Field(alias="lotId") fantasy_team_id: str = Field(alias="fantasyTeamId") fantasy_team_name: str = Field(alias="fantasyTeamName") amount_credits: int = Field(alias="amountCredits") placed_at: str = Field(alias="placedAt")
