def test_validate_competition_ids_rejects_duplicates() -> None: duplicate = UUID("00000000-0000-4000-8000-000000000001") ids = [duplicate, duplicate, UUID("00000000-0000-4000-8000-000000000002")] with pytest.raises(ValidationAuthError, match="una sola volta"): validate_competition_ids(ids)
def test_validate_competition_ids_accepts_three_unique() -> None: ids = [ UUID("00000000-0000-4000-8000-000000000001"), UUID("00000000-0000-4000-8000-000000000002"), UUID("00000000-0000-4000-8000-000000000003"), ] assert validate_competition_ids(ids) == ids

