}

export interface MarketBid {
  id: string;
  sessionId: string;
  fantasyTeamId: string;
  athleteId: string;
  athleteName: string;
  amountCredits: number;
  status: MarketBidStatus;
  submittedAt: string;
  releaseAthleteId: string | null;
  releaseAthleteName: string | null;
}

